/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAggregate = require( './aggregate/get.js' );
var setAggregate = require( './aggregate/set.js' );

var getData = require( './data/get.js' );
var setData = require( './data/set.js' );

var getField = require( './field/get.js' );
var setField = require( './field/set.js' );

var getGroupby = require( './groupby/get.js' );
var setGroupby = require( './groupby/set.js' );

var getName = require( './name/get.js' );
var setName = require( './name/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:facet-mark:main' );


// MAIN //

/**
* Facet constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {Object} [options.aggregate] -
* @param {string} [options.data] -
* @param {Field} [options.field] -
* @param {Field|Array<Field>} [options.groupby] -
* @param {string} [options.name] -
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Facet} facet instance
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
* // returns <Facet>
*/
function Facet( options ) {
	var nargs;
	var self;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Facet ) ) {
		if ( nargs ) {
			return new Facet( options );
		}
		return new Facet();
	}
	self = this;
	EventEmitter.call( this );

	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	this._addChangeListener( this._aggregate );
	this._addChangeListener( this._field );
	this._addChangeListener( this._groupby );

	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Check for required properties...
		if ( !hasProp( options, 'data' ) ) {
			throw new TypeError( 'invalid argument. Options argument must specify the facet data.' );
		}
		if ( !hasProp( options, 'field' ) ) {
			throw new TypeError( 'invalid argument. Options argument must specify the facet field.' );
		}
		if ( !hasProp( options, 'groupby' ) ) {
			throw new TypeError( 'invalid argument. Options argument must specify the facet groupby.' );
		}
		if ( !hasProp( options, 'name' ) ) {
			throw new TypeError( 'invalid argument. Options argument must specify the facet name.' );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit facet the `EventEmitter` prototype.
*/
inherit( Facet, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Facet
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Facet, 'name', 'Facet' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof Facet.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {Facet} facet instance
*/
setNonEnumerableReadOnly( Facet.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof Facet.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {Facet} facet instance
*/
setNonEnumerableReadOnly( Facet.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof Facet.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {Facet} facet instance
*/
setNonEnumerableReadOnly( Facet.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof Facet.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {Facet} facet instance
*/
setNonEnumerableReadOnly( Facet.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* AGGREGATE
*
* @name aggregate
* @memberof Facet.prototype
* @type {(Object|void)}
*
* @example
* var AggregateFacetTransform = require( '@stdlib/plot/vega/transform/' );
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var transform = new AggregateFacetTransform();
*
* var facet = new Facet({
*     'aggregate': transform,
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.aggregate;
* // returns <AggregateFacetTransform>
*/
setReadWriteAccessor( Facet.prototype, 'aggregate', getAggregate, setAggregate );

/**
* DATA
*
* @name data
* @memberof Facet.prototype
* @type {string}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.data;
* // returns 'foo bar'
*/
setReadWriteAccessor( Facet.prototype, 'data', getData, setData );

/**
* FIELD
*
* @name field
* @memberof Facet.prototype
* @type {Field}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.field;
* // returns <Field>
*/
setReadWriteAccessor( Facet.prototype, 'field', getField, setField );

/**
* GROUPBY
*
* @name groupby
* @memberof Facet.prototype
* @type {(Field|Array<Field>)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.groupby;
* // returns <Field>
*/
setReadWriteAccessor( Facet.prototype, 'groupby', getGroupby, setGroupby );

/**
* NAME
*
* @name name
* @memberof Facet.prototype
* @type {string}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.name;
* // returns 'beep boop'
*/
setReadWriteAccessor( Facet.prototype, 'name', getName, setName );

/**
* Facet properties.
*
* @name properties
* @memberof Facet.prototype
* @type {Array<string>}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Facet.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Facet.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'sum',
*     'as': 'sum_field'
* })
* var facet = new Facet({
*     'data': 'foo bar',
*     'field': field,
*     'groupby': field,
*     'name': 'beep boop'
* });
*
* var v = facet.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Facet.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Facet;
